CREATE TABLE "PRESCRIPTION_SERVICE"."PAYER_NOTIFICATIONS"
(
	"PAYER_NOTIFICATION_ID" NUMBER GENERATED BY DEFAULT AS IDENTITY (START WITH 1) NOT NULL,
    "PAYER_ID"  VARCHAR2(20),
    "E_PRESCRIPTION_REFERENCE_NUMBER"  VARCHAR2(100),
    "APPROVAL_REFERENCE_NUMBER"  VARCHAR2(200),
    "STATUS" VARCHAR2(10) NOT NULL,
    "ACK_DATE_TIME" DATE NOT NULL,
    CONSTRAINT PK_PAYER_NOTIFICATION_ID PRIMARY KEY ("PAYER_NOTIFICATION_ID")
);
